                                o.addCandidate(candidate)
                                done(kotlin.Result.success(w))
                            } catch (e: Throwable) {
                                done(kotlin.Result.failure(e))
                            }
                        }
                    }
                    11 -> { // Stats
                        r.check()
                        return AsukaModules.scope.launch(Dispatchers.Main) {
                            try {
                                val w = AsukaNativeWriter.ok()
                                val v = o.stats()
                                Wire.writeStats(w, v)
                                done(kotlin.Result.success(w))
                            } catch (e: Throwable) {
                                done(kotlin.Result.failure(e))
                            }
                        }
                    }
                }
            }
            2 -> {
                val o = obj as DataChannel
                when (method) {
                    1 -> { // Events
                        val sendID = r.callback()
                        val send: (ChannelEvent) -> kotlin.Unit = { a0 ->
                            val w = AsukaNativeWriter()
                            Wire.writeChannelEvent(w, a0)
                            AsukaModules.notify(sendID, w)
                        }
                        r.check()
                        return AsukaModules.scope.launch(Dispatchers.Main) {
                            try {
                                val w = AsukaNativeWriter.ok()
                                o.events(send)
                                done(kotlin.Result.success(w))
                            } catch (e: Throwable) {
                                done(kotlin.Result.failure(e))
                            }
                        }
                    }
                }
            }
        }
        throw AsukaUnsupportedException("no method $iface.$method")
    }

    override fun makeView(name: String, ctx: AsukaNativeContext): AsukaNativeView? = when (name) {
        "VideoView" -> AsukaViewVideoView(ctx)
        else -> null
    }
}

/** The package's values on the wire (core/src/native's format). */
private object Wire {
    fun writeAudio(w: AsukaNativeWriter, v: Audio) {
        w.bool(v.echoCancellation)
        w.bool(v.noiseSuppression)
        w.bool(v.autoGainControl)
    }

    fun readAudio(r: AsukaNativeReader): Audio {
        val f0 = r.bool()
        val f1 = r.bool()
        val f2 = r.bool()
        return Audio(echoCancellation = f0, noiseSuppression = f1, autoGainControl = f2)
    }

    fun writeCandidate(w: AsukaNativeWriter, v: Candidate) {
        w.string(v.candidate)
        w.string(v.sdpMid)
        w.int(v.sdpMLineIndex)
    }

    fun readCandidate(r: AsukaNativeReader): Candidate {
        val f0 = r.string()
        val f1 = r.string()
        val f2 = r.int()
        return Candidate(candidate = f0, sdpMid = f1, sdpMLineIndex = f2)
    }

    fun writeChannelEvent(w: AsukaNativeWriter, v: ChannelEvent) {
        w.int(v.kind.value)
        w.bool(v.binary)
        w.string(v.text)
        w.data(v.data)
    }

    fun readChannelEvent(r: AsukaNativeReader): ChannelEvent {
        val f0 = ChannelEventKind(r.int())
        val f1 = r.bool()
        val f2 = r.string()
        val f3 = r.data()
        return ChannelEvent(kind = f0, binary = f1, text = f2, data = f3)
    }

    fun writeChannelInfo(w: AsukaNativeWriter, v: ChannelInfo) {
        w.int(v.handle)
        w.string(v.label)
        w.bool(v.ordered)
        w.string(v.protocol)
        w.int(v.id)
    }

    fun readChannelInfo(r: AsukaNativeReader): ChannelInfo {
        val f0 = r.int()
        val f1 = r.string()
        val f2 = r.bool()
        val f3 = r.string()
        val f4 = r.int()
        return ChannelInfo(handle = f0, label = f1, ordered = f2, protocol = f3, id = f4)
    }

    fun writeChannelOptions(w: AsukaNativeWriter, v: ChannelOptions) {
        w.bool(v.ordered)
        Wire.writeOptInt(w, v.maxRetransmits)
        Wire.writeOptDuration(w, v.maxPacketLifeTime)
        w.string(v.protocol)
        Wire.writeOptInt(w, v.id)
    }

    fun readChannelOptions(r: AsukaNativeReader): ChannelOptions {
        val f0 = r.bool()
        val f1 = Wire.readOptInt(r)
        val f2 = Wire.readOptDuration(r)
        val f3 = r.string()
        val f4 = Wire.readOptInt(r)
        return ChannelOptions(ordered = f0, maxRetransmits = f1, maxPacketLifeTime = f2, protocol = f3, id = f4)
    }

    fun writeConfig(w: AsukaNativeWriter, v: Config) {
        Wire.writeSliceIceServer(w, v.iceServers)
        w.int(v.policy.value)
    }

    fun readConfig(r: AsukaNativeReader): Config {
        val f0 = Wire.readSliceIceServer(r)
        val f1 = IcePolicy(r.int())
        return Config(iceServers = f0, policy = f1)
    }

    fun writeConnection(w: AsukaNativeWriter, v: Connection?) {
        w.int64(if (v == null) 0L else AsukaModules.retain(v, AsukaModule, 1))
    }

    fun readConnection(r: AsukaNativeReader): Connection? = AsukaModules.obj(r.int64()) as? Connection

    fun writeDataChannel(w: AsukaNativeWriter, v: DataChannel?) {
        w.int64(if (v == null) 0L else AsukaModules.retain(v, AsukaModule, 2))
    }

    fun readDataChannel(r: AsukaNativeReader): DataChannel? = AsukaModules.obj(r.int64()) as? DataChannel

    fun writeDescription(w: AsukaNativeWriter, v: Description) {
        w.int(v.kind.value)
        w.string(v.sdp)
    }

    fun readDescription(r: AsukaNativeReader): Description {
        val f0 = SdpKind(r.int())
        val f1 = r.string()
        return Description(kind = f0, sdp = f1)
    }

    fun writeMedia(w: AsukaNativeWriter, v: Media) {
        Wire.writeOptTrack(w, v.audio)
        Wire.writeOptTrack(w, v.video)
    }

    fun readMedia(r: AsukaNativeReader): Media {
        val f0 = Wire.readOptTrack(r)
        val f1 = Wire.readOptTrack(r)
        return Media(audio = f0, video = f1)
    }

    fun writeOptAudio(w: AsukaNativeWriter, v: Audio?) {
        w.present(v != null)
        if (v != null) Wire.writeAudio(w, v)
    }

    fun readOptAudio(r: AsukaNativeReader): Audio? = if (r.present()) Wire.readAudio(r) else null

    fun writeOptVideo(w: AsukaNativeWriter, v: Video?) {
        w.present(v != null)
        if (v != null) Wire.writeVideo(w, v)
    }

    fun readOptVideo(r: AsukaNativeReader): Video? = if (r.present()) Wire.readVideo(r) else null

    fun writePeerEvent(w: AsukaNativeWriter, v: PeerEvent) {
        w.int(v.kind.value)
        Wire.writeCandidate(w, v.candidate)
        w.int(v.connection.value)
        w.int(v.ice.value)
        w.int(v.signaling.value)
        w.int(v.gathering.value)
        Wire.writeTrack(w, v.track)
        Wire.writeChannelInfo(w, v.channel)
    }

    fun readPeerEvent(r: AsukaNativeReader): PeerEvent {
        val f0 = EventKind(r.int())
        val f1 = Wire.readCandidate(r)
        val f2 = ConnectionState(r.int())
        val f3 = IceState(r.int())
        val f4 = SignalingState(r.int())
        val f5 = GatheringState(r.int())
        val f6 = Wire.readTrack(r)
        val f7 = Wire.readChannelInfo(r)
        return PeerEvent(kind = f0, candidate = f1, connection = f2, ice = f3, signaling = f4, gathering = f5, track = f6, channel = f7)
    }

    fun writeSliceAudioRoute(w: AsukaNativeWriter, v: List<AudioRoute>) {
        w.len(v.size)
        for (e in v) w.int(e.value)
    }

    fun readSliceAudioRoute(r: AsukaNativeReader): List<AudioRoute> {
        val n = r.len()
        return List(n) { AudioRoute(r.int()) }
    }

    fun writeStats(w: AsukaNativeWriter, v: Stats) {
        w.int(v.bytesSent)
        w.int(v.bytesReceived)
        w.int(v.packetsSent)
        w.int(v.packetsReceived)
        w.int(v.packetsLost)
        w.duration(v.roundTripTime)
        w.float64(v.availableOutgoingBitrate)
        w.string(v.localCandidate)
        w.string(v.remoteCandidate)
        w.int(v.frameWidth)
        w.int(v.frameHeight)
        w.float64(v.framesPerSecond)
    }

    fun readStats(r: AsukaNativeReader): Stats {
        val f0 = r.int()
        val f1 = r.int()
        val f2 = r.int()
        val f3 = r.int()
        val f4 = r.int()
        val f5 = r.duration()
        val f6 = r.float64()
        val f7 = r.string()
        val f8 = r.string()
        val f9 = r.int()
        val f10 = r.int()
        val f11 = r.float64()
        return Stats(bytesSent = f0, bytesReceived = f1, packetsSent = f2, packetsReceived = f3, packetsLost = f4, roundTripTime = f5, availableOutgoingBitrate = f6, localCandidate = f7, remoteCandidate = f8, frameWidth = f9, frameHeight = f10, framesPerSecond = f11)
    }

    fun writeTrack(w: AsukaNativeWriter, v: Track) {
        w.string(v.id)
        w.int(v.kind.value)
        w.bool(v.remote)
        w.int(v.facing.value)
    }

    fun readTrack(r: AsukaNativeReader): Track {
        val f0 = r.string()
        val f1 = TrackKind(r.int())
        val f2 = r.bool()
        val f3 = Facing(r.int())
        return Track(id = f0, kind = f1, remote = f2, facing = f3)
    }

    fun writeVideo(w: AsukaNativeWriter, v: Video) {
        w.int(v.facing.value)
        w.int(v.width)
        w.int(v.height)
        w.int(v.frameRate)
        w.bool(v.pattern)
    }

    fun readVideo(r: AsukaNativeReader): Video {
        val f0 = Facing(r.int())
        val f1 = r.int()
        val f2 = r.int()
        val f3 = r.int()
        val f4 = r.bool()
        return Video(facing = f0, width = f1, height = f2, frameRate = f3, pattern = f4)
    }

    fun writeVideoSize(w: AsukaNativeWriter, v: VideoSize) {
        w.int(v.width)
        w.int(v.height)
    }

    fun readVideoSize(r: AsukaNativeReader): VideoSize {
        val f0 = r.int()
        val f1 = r.int()
        return VideoSize(width = f0, height = f1)
    }

    fun writeIceServer(w: AsukaNativeWriter, v: IceServer) {
        Wire.writeSliceString(w, v.urls)
        w.string(v.username)
        w.string(v.credential)
    }

    fun readIceServer(r: AsukaNativeReader): IceServer {
        val f0 = Wire.readSliceString(r)
        val f1 = r.string()
        val f2 = r.string()
        return IceServer(urls = f0, username = f1, credential = f2)
    }

    fun writeOptDuration(w: AsukaNativeWriter, v: kotlin.time.Duration?) {
        w.present(v != null)
        if (v != null) w.duration(v)
    }

    fun readOptDuration(r: AsukaNativeReader): kotlin.time.Duration? = if (r.present()) r.duration() else null

    fun writeOptInt(w: AsukaNativeWriter, v: Long?) {
        w.present(v != null)
        if (v != null) w.int(v)
    }

    fun readOptInt(r: AsukaNativeReader): Long? = if (r.present()) r.int() else null

    fun writeOptTrack(w: AsukaNativeWriter, v: Track?) {
        w.present(v != null)
        if (v != null) Wire.writeTrack(w, v)
    }

    fun readOptTrack(r: AsukaNativeReader): Track? = if (r.present()) Wire.readTrack(r) else null

    fun writeSliceIceServer(w: AsukaNativeWriter, v: List<IceServer>) {
        w.len(v.size)
        for (e in v) Wire.writeIceServer(w, e)
    }

    fun readSliceIceServer(r: AsukaNativeReader): List<IceServer> {
        val n = r.len()
        return List(n) { Wire.readIceServer(r) }
    }

    fun writeSliceString(w: AsukaNativeWriter, v: List<String>) {
        w.len(v.size)
        for (e in v) w.string(e)
    }

    fun readSliceString(r: AsukaNativeReader): List<String> {
        val n = r.len()
        return List(n) { r.string() }
    }

}
